export function getCountryFlag(countryName) {
  return COUNTRY_FLAGS[countryName] || "🌍";
}

export function getCountryDetails(countryName, countryStats = {}) {
  if (!countryName) return null;
  const flag = getCountryFlag(countryName);
  const loc = countryStats[countryName];
  const hasUsers = Boolean(loc && loc.usersCount > 0);

  return {
    name: countryName,
    code: loc?.code || countryName.slice(0, 3).toUpperCase(),
    flag,
    usersCount: hasUsers ? loc.usersCount : 0,
    topCity: hasUsers ? loc.topCity : null,
    cities: hasUsers ? loc.cities : [],
    lastActive: hasUsers ? loc.lastActive : null,
    tier: hasUsers ? loc.tier : 0,
    label: hasUsers ? loc.label : 'No downloads yet',
    hasUsers,
  };
}
